INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (17, 23, 'theory', 'Quiz: oVirt automation');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 23, 0, 'How is an action, such as starting a virtual machine, expressed in the oVirt REST API?', '["GET on /vms/123?start=true", "PUT on the /vms collection with the machine name", "POST on /vms/123/start", "DELETE on /vms/123/start"]', 2, 'Actions are a POST to the resource with the action name at the end; parameters such as async go in the body. GET must not change state.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 23, 1, 'Why is a bearer token from SSO better than basic authentication in scripts?', '["The password is sent once, the token lives a limited time, and after a 401 you request a new one", "A token never expires, so retries are unnecessary", "The engine does not support basic authentication at all", "A token can be refreshed forever without the password"]', 0, 'The password travels only when the token is obtained. The token is time-limited and has no refresh: on a 401 you request a new one.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 23, 2, 'What does state: present mean in the ovirt_vm module?', '["Create the machine and always start it", "Stop the machine if it is running", "Delete the machine", "Create or update the machine without changing its power state"]', 3, 'present creates or updates the machine and leaves power as it is. running starts it, stopped stops it, absent deletes it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 23, 3, 'Why is a Linux template sealed before cloning?', '["To make the disk faster", "To remove machine-specific data such as host keys and the machine ID so that clones are not twins", "To forbid deleting the template", "To compress the disk image"]', 1, 'Sealing wipes machine-specific details such as host keys, the machine ID, and logs, and cloud-init then supplies the name, network, and access keys on first boot.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (17, 23, 4, 'Which retry strategy is safe for automation?', '["Retry any failed POST immediately in a tight loop", "Retry under the administrator account to bypass permissions", "Retry reads and desired-state operations with a growing pause and random jitter", "Never wait between attempts"]', 2, 'Reads and idempotent operations can be repeated; a growing pause with jitter does not overload the engine. A blind retry of a create may produce a duplicate.');
